"""Automatic checks for the Python Readiness Test. Do not edit this file.

Test names start with task1_ ... task4_ so results can be counted per task.
"""
import pytest

import readiness_test as rt


# Task 1
@pytest.mark.parametrize("amount, band", [
    (15000, "High"), (10000, "High"), (9999.99, "Medium"),
    (1000, "Medium"), (999, "Low"), (250.5, "Low"), (0, "Low"),
])
def test_task1_classify_amount(amount, band):
    assert rt.classify_amount(amount) == band


# Task 2
def test_task2_total_by_type():
    txns = [("card", 120), ("transfer", 500), ("card", 80)]
    assert rt.total_by_type(txns) == {"card": 200, "transfer": 500}
    assert rt.total_by_type([("fee", 2.5)]) == {"fee": 2.5}


def test_task2_total_by_type_empty():
    assert rt.total_by_type([]) == {}


# Task 3
@pytest.mark.parametrize("text, value", [
    ("1,250.50", 1250.5), (" 300 ", 300.0), ("42", 42.0), ("-15.5", -15.5),
    ("n/a", None), ("", None), ("12abc", None),
])
def test_task3_parse_amount(text, value):
    assert rt.parse_amount(text) == value


# Task 4
def test_task4_read_amounts(tmp_path):
    f = tmp_path / "amounts.txt"
    f.write_text("100\n1,200.50\n\nunknown\n75\n")
    assert rt.read_amounts(f) == [100.0, 1200.5, 75.0]


def test_task4_read_amounts_empty_file(tmp_path):
    f = tmp_path / "empty.txt"
    f.write_text("")
    assert rt.read_amounts(f) == []
